    // =================================
    arquivo_produtos = fopen("produtos.txt", "r");
    if (arquivo_produtos == NULL) {
        printf("O arquivo produtos.txt nao foi encontrado.\n");
        free(produtos);
        free(vendas);
        return 1;
    }

    // Leitura adaptada para ';' como delimitador
    while (ler_dados_delimitados(arquivo_produtos, 
                                &produtos[tam_produtos].codigo_produto, 
                                &produtos[tam_produtos].qtd_estoque, 
                                &produtos[tam_produtos].qtd_minima, ';')) {
        tam_produtos++;
        // Realoção: Tamanho atual + 1
        produtos = (struct Produtos *)realloc(produtos, sizeof(struct Produtos) * (tam_produtos + 1));
        if (produtos == NULL) {
            perror("Erro na realocação de produtos");
            fclose(arquivo_produtos);
            free(produtos);
            free(vendas);
            return 1;
        }
    }
    fclose(arquivo_produtos);
    printf("Leitura de produtos concluida. Total: %d.\n", tam_produtos);


    // =================================
