    // =================================
    arquivo_vendas = fopen("vendas.txt", "r");
    if (arquivo_vendas == NULL) {
        printf("O arquivo vendas.txt nao foi encontrado.\n");
        free(produtos);
        free(vendas);
        return 1;
    }

    // Leitura adaptada para ';' como delimitador (Código;QtVendida;ValorUnitario;Canal)
    while (ler_dados_delimitados(arquivo_vendas, 
                                &vendas[tam_vendas].codigo_produto, 
                                &vendas[tam_vendas].quantidade_vendida, 
                                &vendas[tam_vendas].valor_unitario, ';')) {
        tam_vendas++;
        // Realoção: Tamanho atual + 1
        vendas = (struct Vendas *)realloc(vendas, sizeof(struct Vendas) * (tam_vendas + 1));
        if (vendas == NULL) {
            perror("Erro na realocação de vendas");
            fclose(arquivo_vendas);
            free(produtos);
            free(vendas);
