        }
    }
    fclose(arquivo_vendas);
    printf("Leitura de vendas concluida. Total: %d.\n", tam_vendas);


    // =================================
    // 3. PROCESSA AS INFORMAÇÕES
    // =================================
    for (i = 0; i < tam_produtos; i++) {
        produtos[i].qtd_vendida = 0;
        // Soma total de vendas para este produto
        for (j = 0; j < tam_vendas; j++) {
            if (vendas[j].codigo_produto == produtos[i].codigo_produto) {
                produtos[i].qtd_vendida += vendas[j].quantidade_vendida;
            }
        }

        // Cálculo do Estoque APÓS venda
        produtos[i].estoque_apos_venda = produtos[i].qtd_estoque - produtos[i].qtd_vendida;

        // Necessidade de Transferência: Qtd_Mínima - Estoque_APÓS_Venda
        produtos[i].necessidade_transferencia = produtos[i].qtd_minima - produtos[i].estoque_apos_venda;

        // Se não houver déficit (Estoque_APÓS_Venda >= Qtd_Mínima), a necessidade é 0.
        if (produtos[i].necessidade_transferencia < 0) {
            produtos[i].necessidade_transferencia = 0;
        }

        // Qtd Transferência: A necessidade é a quantidade que precisa ser reposta
        // (Assumimos que a transferência é igual à necessidade se houver).
        produtos[i].qtd_transferencia = produtos[i].necessidade_transferencia;

        // Nota: Os cálculos no seu arquivo Transfere.txt parecem mais complexos do que apenas
        // (Qtd_Mínima - Estoque_APÓS_Venda). Se o seu objetivo é replicar exatamente o TXT, 
