    // =================================
    arquivo_divergencias = fopen("divergencias.txt", "w");
    if (arquivo_divergencias == NULL) {
        printf("Erro ao criar arquivo de divergencias.\n");
        free(produtos);
        free(vendas);
        return 1;
    }

    // O loop de divergências está incorreto. Ele compara CADA venda com TODOS os produtos,
    // em vez de procurar o produto correspondente uma vez.
    for (i = 0; i < tam_vendas; i++) {
        // Busca o produto correspondente
        for (j = 0; j < tam_produtos; j++) {
            if (vendas[i].codigo_produto == produtos[j].codigo_produto) {

                // Divergência 1: Venda > Estoque (IMPORTANTE: verificar estoque ANTES da venda)
                // Se o estoque inicial (produtos[j].qtd_estoque) era insuficiente para esta venda:
                if (vendas[i].quantidade_vendida > produtos[j].qtd_estoque) {
