    arquivo_produtos = fopen("produtos.txt", "r");
    if (arquivo_produtos == NULL) {
        printf("O arquivo produtos nao foi encontrado.");
        return 1;
    }
    while (fscanf(arquivo_produtos, "%d;%d;%d\n", &produtos[tam_produtos].codigo_produto, &produtos[tam_produtos].qtd_estoque, &produtos[tam_produtos].qtd_minima) != EOF) {
        tam_produtos++;
        produtos = (struct Produtos *)realloc(produtos, sizeof(struct Produtos) * (tam_produtos + 1));
    }
